import sys

def main():
    import sys
    import itertools

    def can_form_paths(L, R, n):
        if R - L + 1 > 2 ** (n - 2):
            return False
        return True

    def generate_city(L, R):
        n = 2
        while n <= 32:
            if can_form_paths(L, R, n):
                m = 0
                roads = []
                lengths = set()
                for path in itertools.product([0, 1], repeat=n-2):
                    length = 0
                    prev = 1
                    for i, bit in enumerate(path):
                        if bit == 1:
                            length += 1
                            roads.append((prev, i + 2, 1))
                            prev = i + 2
                    length += 1
                    roads.append((prev, n, 1))
                    lengths.add(length)
                    m += len(path) + 1
                    if len(lengths) == R - L + 1:
                        break
                if len(lengths) == R - L + 1:
                    min_length = min(lengths)
                    max_length = max(lengths)
                    if min_length == L and max_length == R:
                        return n, m, roads
            n += 1
        return None

    L, R = map(int, sys.stdin.read().strip().split())
    result = generate_city(L, R)
    if result is None:
        print("NO")
    else:
        n, m, roads = result
        print("YES")
        print(n, m)
        for a, b, c in roads:
            print(a, b, c)

main()
